const edgePops = 200;
const missesPerPop = 50; // cold misses streaming in during the fill window
const totalEdgeMisses = edgePops * missesPerPop; // 10000

// Without shield: every edge miss is its own origin request
const originReqNoShield = totalEdgeMisses;

// With shield: 1 request fills it, then it absorbs 90% of the rest
const shieldAbsorbRate = 0.90;
const originReqWithShield = 1 + Math.round((totalEdgeMisses - 1) * (1 - shieldAbsorbRate));

const offloadPct = (100 * (1 - originReqWithShield / originReqNoShield)).toFixed(1);

console.log('origin requests, no shield:', originReqNoShield);
console.log('origin requests, with shield:', originReqWithShield);
console.log('origin offload:', offloadPct + '%');
